mapper.insert:
INSERT INTO PRODUCT_REVIEWS (
    PRODUCT_ID, USER_ID, ORDER_ITEM_ID, RATING, CONTENT, IMAGE_URL
) VALUES (
    #{productId}, #{userId}, #{orderItemId}, #{rating}, #{content}, #{imageUrl}
)

mapper.select:
SELECT OI.PRODUCT_ID
FROM ORDER_ITEMS OI
JOIN ORDERS O ON O.ORDER_ID = OI.ORDER_ID
WHERE OI.ORDER_ITEM_ID = #{orderItemId}
  AND O.ORDER_CODE = #{orderCode}
  AND O.USER_ID = #{userId}
LIMIT 1

SELECT REVIEW_ID, PRODUCT_ID, USER_ID, ORDER_ITEM_ID, RATING, CONTENT, IMAGE_URL, CREATED_AT
FROM PRODUCT_REVIEWS
WHERE REVIEW_ID = #{reviewId}

mapper.update:
UPDATE PRODUCT_REVIEWS
SET RATING = #{rating},
    CONTENT = #{content},
    IMAGE_URL = #{imageUrl}
WHERE REVIEW_ID = #{reviewId}
